"""Long-term memory with a validity window, so a superseded fact stops being retrieved."""
import datetime

from langchain_community.vectorstores import Chroma
from langchain_openai import OpenAIEmbeddings

store = Chroma(collection_name="user_memory", embedding_function=OpenAIEmbeddings())


def _now():
    return datetime.datetime.utcnow().isoformat()


def supersede(user_id, predicate, at):
    """Close the validity window of any prior fact this one contradicts."""
    for prior in store.get(where={"user_id": user_id, "predicate": predicate})["ids"]:
        store.update_document(prior, metadata={"invalid_at": at})


def remember(user_id, predicate, fact):
    """Persist one fact with an explicit validity window."""
    at = _now()
    supersede(user_id, predicate, at)
    store.add_texts(
        texts=[fact],
        metadatas=[{
            "user_id": user_id,
            "predicate": predicate,
            "valid_at": at,
            "invalid_at": None,
        }],
    )


def recall(user_id, question, as_of=None, k=6):
    """Retrieve only facts whose validity window contains as_of."""
    at = as_of or _now()
    hits = store.similarity_search(question, k=k * 4, filter={"user_id": user_id})
    live = [
        h for h in hits
        if h.metadata["valid_at"] <= at
        and (h.metadata.get("invalid_at") is None or h.metadata["invalid_at"] > at)
    ]
    return "\n".join(h.page_content for h in live[:k])


def build_context(user_id, question):
    return f"Known about the user:\n{recall(user_id, question)}\n\nQuestion: {question}"
